      if (fl_t2172.tag != FL_NUMBER || fl_t2173.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", fl_t2172, fl_t2173, error));
      const fl_value ostatok = fl_number(fl_t2172.as.number - fl_t2173.as.number); /* пусть «остаток» */
      fl_value fl_t2174 = fl_nothing();
      FL_TRY(kompilyator_flang_konchaetsya_na(ctx, nizhnee, okonchanie, &fl_t2174, error));
