/* Тело «Тройки отметок»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_troyki_otmetok_body(fl_ctx *ctx, fl_value elementy, fl_value naydennye, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(elementy)) {
      *result = naydennye;
      return FL_OK;
    } else if (fl_chain_cons(elementy)) {
      const fl_value golova = fl_chain_head(elementy); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(elementy); /* хвост «хвост» */
      fl_value fl_t11101 = fl_nothing();
      FL_TRY(kompilyator_flang_dopisat_troyku_otmetki(ctx, golova, naydennye, &fl_t11101, error));
      elementy = hvost;
      naydennye = fl_t11101;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Тройки отметок", error));
      continue;
    } else {
      return fl_match_fail(ctx, elementy, error);
    }
  }
}

