fl_status kompilyator_flang_troyki_otmetok(fl_ctx *ctx, fl_value elementy, fl_value naydennye, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Тройки отметок", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_troyki_otmetok_body(ctx, elementy, naydennye, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

