      const fl_value fl_t12146 = zhelaemoe;
      const fl_value fl_t12147 = vzyato;
      const fl_value fl_t12148 = fl_number(suffiks.as.number + 1.0);
      zhelaemoe = fl_t12146;
      vzyato = fl_t12147;
      suffiks = fl_t12148;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Свободное имя", error));
