      fl_value fl_t16116 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t16114, gotovye, &fl_t16116, error));
      imena = prochie;
      tipy = fl_t16112;
      gotovye = fl_t16116;
