/* Тело «Список содержит знач»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_spisok_soderzhit_znach_body(fl_ctx *ctx, fl_value elementy, fl_value iskomoe, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(elementy)) {
      *result = fl_flag(false);
      return FL_OK;
    } else if (fl_chain_cons(elementy)) {
      const fl_value pervyy = fl_chain_head(elementy); /* голова «первый» */
      const fl_value prochie = fl_chain_tail(elementy); /* хвост «прочие» */
      fl_value fl_t23508 = fl_nothing();
      FL_TRY(kompilyator_flang_znach_ravny(ctx, pervyy, iskomoe, &fl_t23508, error));
      bool fl_t23509 = false;
      FL_TRY(fl_cond(ctx, fl_t23508, &fl_t23509, error));
      if (fl_t23509) {
        *result = fl_flag(true);
        return FL_OK;
      } else {
        const fl_value fl_t23510 = iskomoe;
        elementy = prochie;
        iskomoe = fl_t23510;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Список содержит знач", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, elementy, error);
    }
  }
}

/*
 * Функция flang «Список содержит знач».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param elementy — «элементы»: список: «Знач»
 * @param iskomoe — «искомое»: «Знач»
 * @return значение
 */
fl_status kompilyator_flang_spisok_soderzhit_znach(fl_ctx *ctx, fl_value elementy, fl_value iskomoe, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Список содержит знач", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_spisok_soderzhit_znach_body(ctx, elementy, iskomoe, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

