/* Тело «Беда спуска»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_beda_spuska_body(fl_ctx *ctx, fl_value vyzovy, fl_value mesto, fl_value parametr, fl_value skolko, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(vyzovy)) {
      *result = kompilyator_flang_text_317;
      return FL_OK;
    } else if (fl_chain_cons(vyzovy)) {
      const fl_value g = fl_chain_head(vyzovy); /* голова «г» */
      const fl_value h = fl_chain_tail(vyzovy); /* хвост «х» */
      fl_value fl_t27068 = fl_nothing();
      FL_TRY(kompilyator_flang_spusk_ne_strogiy(ctx, g, mesto, parametr, skolko, &fl_t27068, error));
      bool fl_t27069 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(fl_t27068, kompilyator_flang_text_317)), &fl_t27069, error));
      if (fl_t27069) {
        const fl_value fl_t27070 = mesto;
        const fl_value fl_t27071 = parametr;
        const fl_value fl_t27072 = skolko;
        vyzovy = h;
        mesto = fl_t27070;
        parametr = fl_t27071;
        skolko = fl_t27072;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Беда спуска", error));
        continue;
      } else {
        return kompilyator_flang_spusk_ne_strogiy(ctx, g, mesto, parametr, skolko, result, error);
      }
    } else {
      return fl_match_fail(ctx, vyzovy, error);
    }
  }
}

