/* Тело «Первое из найденных»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_pervoe_iz_naydennyh_body(fl_ctx *ctx, fl_value funkcii, fl_value imya, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(funkcii)) {
      return kompilyator_flang_uzel_nichto(ctx, result, error);
    } else if (fl_chain_cons(funkcii)) {
      const fl_value g = fl_chain_head(funkcii); /* голова «г» */
      const fl_value h = fl_chain_tail(funkcii); /* хвост «х» */
      fl_value fl_t28255 = fl_nothing();
      FL_TRY(kompilyator_flang_postusloviya_po_imeni(ctx, g, imya, &fl_t28255, error));
      fl_value fl_t28256 = fl_nothing(); /* «пусто» */
      FL_TRY(fl_b_pusto(ctx, fl_t28255, &fl_t28256, error));
      bool fl_t28257 = false;
      FL_TRY(fl_cond(ctx, fl_t28256, &fl_t28257, error));
      if (fl_t28257) {
        const fl_value fl_t28258 = imya;
        funkcii = h;
        imya = fl_t28258;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Первое из найденных", error));
        continue;
      } else {
        *result = g;
        return FL_OK;
      }
    } else {
      return fl_match_fail(ctx, funkcii, error);
    }
  }
}

