/* Тело «Пройти посылки случаями»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_proyti_posylki_sluchayami_body(fl_ctx *ctx, fl_value posylki, fl_value svod, fl_value programma, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(posylki)) {
      *result = svod;
      return FL_OK;
    } else if (fl_chain_cons(posylki)) {
      const fl_value g = fl_chain_head(posylki); /* голова «г» */
      const fl_value h = fl_chain_tail(posylki); /* хвост «х» */
      fl_value fl_t29230 = fl_nothing();
      FL_TRY(kompilyator_flang_uchest_posylku_sluchaem(ctx, g, svod, programma, &fl_t29230, error));
      const fl_value fl_t29231 = programma;
      posylki = h;
      svod = fl_t29230;
      programma = fl_t29231;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пройти посылки случаями", error));
      continue;
    } else {
      return fl_match_fail(ctx, posylki, error);
    }
  }
}

