        FL_TRY(kompilyator_flang_polozhit_zamenu(ctx, zameny, fl_t29420, ga, &fl_t29421, error));
        parametry = hp;
        argumenty = ha;
        zameny = fl_t29421;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Замены вызова", error));
