/* Тело «Строка раньше»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_stroka_ranshe_body(fl_ctx *ctx, fl_value pervaya, fl_value vtoraya, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(pervaya)) {
      if (fl_chain_empty(vtoraya)) {
        *result = fl_flag(false);
        return FL_OK;
      } else if (fl_chain_cons(vtoraya)) {
        const fl_value vg = fl_chain_head(vtoraya); /* голова «вг» */
        const fl_value vh = fl_chain_tail(vtoraya); /* хвост «вх» */
        (void)vg;
        (void)vh;
        *result = fl_flag(true);
        return FL_OK;
      } else {
        return fl_match_fail(ctx, vtoraya, error);
      }
    } else if (fl_chain_cons(pervaya)) {
      const fl_value pg = fl_chain_head(pervaya); /* голова «пг» */
      const fl_value ph = fl_chain_tail(pervaya); /* хвост «пх» */
      if (fl_chain_empty(vtoraya)) {
        *result = fl_flag(false);
        return FL_OK;
      } else if (fl_chain_cons(vtoraya)) {
        const fl_value vg_2 = fl_chain_head(vtoraya); /* голова «вг» */
        const fl_value vh_2 = fl_chain_tail(vtoraya); /* хвост «вх» */
        bool fl_t29645 = false;
        FL_TRY(fl_cond(ctx, fl_flag(fl_equal(pg, vg_2)), &fl_t29645, error));
        if (fl_t29645) {
          pervaya = ph;
          vtoraya = vh_2;
          /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
          FL_TRY(fl_tick(ctx, "Строка раньше", error));
          continue;
        } else {
          fl_value fl_t29646 = fl_nothing(); /* «код символа» */
          FL_TRY(fl_b_kod_simvola_dokazano(ctx, pg, &fl_t29646, error));
          fl_value fl_t29647 = fl_nothing(); /* «код символа» */
          FL_TRY(fl_b_kod_simvola_dokazano(ctx, vg_2, &fl_t29647, error));
          if (fl_t29646.tag != FL_NUMBER || fl_t29647.tag != FL_NUMBER) FL_TRY(fl_not_order(ctx, fl_t29646, fl_t29647, error));
          *result = fl_flag(fl_t29646.as.number < fl_t29647.as.number);
          return FL_OK;
        }
      } else {
        return fl_match_fail(ctx, vtoraya, error);
      }
    } else {
      return fl_match_fail(ctx, pervaya, error);
    }
  }
}

